func Run(ag agent.AgentInterface, initialTask string) error {
	// 保存终端状态，确保退出时恢复。
	// tview/tcell 在 Windows cmd.exe 上有时不能完整恢复控制台模式，
	// 导致退出后出现 ANSI 转义序列乱码。
	fd := int(os.Stdin.Fd())
	oldState, err := term.GetState(fd)
	if err == nil {
		defer term.Restore(fd, oldState)
	}

	m := NewModel(ag, initialTask)
	return m.Build().Run()
}

