// parseXMLToolCalls 从 XML 格式的 tool_call 块中提取 ToolCall 列表。
// Ollama 的 qwen3-coder 等模型可能返回如下格式：
//
//	<tool_call>
//	{"name": "read_file", "arguments": {"path": "main.go"}}
//	</tool_call>
func parseXMLToolCalls(content string) []ToolCall {
	var calls []ToolCall
	// 提取所有 <tool_call>...</tool_call> 之间的 JSON
	re := regexp.MustCompile(`<tool_call>\s*\n?(.*?)\n?\s*</tool_call>`)
	matches := re.FindAllStringSubmatch(content, -1)
	for i, m := range matches {
		if len(m) < 2 {
			continue
		}
		jsonStr := strings.TrimSpace(m[1])
		var tc struct {
			Name      string         `json:"name"`
			Arguments json.RawMessage `json:"arguments"`
		}
		if err := json.Unmarshal([]byte(jsonStr), &tc); err != nil {
			continue
		}
		calls = append(calls, ToolCall{
			ID:   fmt.Sprintf("xml_%d", i),
			Type: "function",
			Function: FunctionCall{
				Name:      tc.Name,
				Arguments: string(tc.Arguments),
			},
		})
	}
	return calls
}

