)

// WritePlanTool 把任务拆解结构写到 .aicode/plan.md，
// 让模型"先规划再执行"，每完成一步更新状态。
type WritePlanTool struct{}

func (WritePlanTool) Name() string { return "write_plan" }

func (WritePlanTool) Description() string {
	return "创建或更新任务计划。对于需要多个步骤的复杂任务，" +
		"先写计划再按步执行，完成一步更新一步（status 用 pending/in_progress/done）。" +
		"计划保存在 .aicode/plan.md，方便跨会话继续。"
}

func (WritePlanTool) Schema() map[string]any {
	return map[string]any{
		"type": "object",
		"properties": map[string]any{
			"steps": map[string]any{
				"type": "array",
				"items": map[string]any{
					"type": "object",
					"properties": map[string]any{
						"id":     map[string]any{"type": "string", "description": "步骤编号，如 1、2a、2b"},
						"title":  map[string]any{"type": "string", "description": "步骤简述"},
						"status": map[string]any{"type": "string", "description": "pending | in_progress | done"},
					},
					"required": []string{"id", "title", "status"},
				},
				"description": "计划步骤列表。每次调用传当前全部步骤和最新状态，会整体覆盖。",
			},
		},
		"required": []string{"steps"},
	}
}

// 计划文件不需要审批（副作用低，且频繁更新）。
func (WritePlanTool) Execute(args json.RawMessage) (string, error) {
	var p struct {
		Steps []struct {
			ID     string `json:"id"`
			Title  string `json:"title"`
			Status string `json:"status"`
		} `json:"steps"`
	}
	if err := json.Unmarshal(args, &p); err != nil {
		return "", fmt.Errorf("参数解析失败: %w", err)
	}
	if len(p.Steps) == 0 {
		return "", fmt.Errorf("steps 不能为空")
	}

	dir, err := EnsureWorkspaceDir()
	if err != nil {
		return "", err
	}

	var md strings.Builder
	md.WriteString("# 任务计划\n\n")
	md.WriteString("| # | 状态 | 任务 |\n")
	md.WriteString("|---|------|------|\n")
	done := 0
	for _, s := range p.Steps {
		icon := map[string]string{
			"pending":    "⬜",
			"in_progress": "🔄",
			"done":       "✅",
		}[s.Status]
		if icon == "" {
			icon = "⬜"
		}
		if s.Status == "done" {
			done++
		}
		md.WriteString(fmt.Sprintf("| %s | %s | %s |\n", s.ID, icon, s.Title))
	}
	md.WriteString(fmt.Sprintf("\n> 进度：%d/%d 完成\n", done, len(p.Steps)))

	if err := os.WriteFile(filepath.Join(dir, "plan.md"), []byte(md.String()), 0o644); err != nil {
		return "", err
	}
	return fmt.Sprintf("计划已更新（%d/%d 完成）", done, len(p.Steps)), nil
}

package tools

import (
	"regexp"
	"strings"
)

// dangerousPatterns 是被直接拒绝执行的危险命令模式。
// 命中任意一条，命令都不会执行，而是返回拦截说明给模型。
// 覆盖：递归删除、磁盘格式化/擦写、关机重启、fork 炸弹、远程管道执行、
// 覆盖系统关键路径、危险提权等。
var dangerousPatterns = []*regexp.Regexp{
	// 递归强制删除（rm -rf / rm -fr 各种写法）
	regexp.MustCompile(`\brm\s+(-[a-z]*\s+)*-[a-z]*[rf][a-z]*`),
	// Windows 递归删除
	regexp.MustCompile(`(?i)\b(del|erase)\b.*(/s|/q)`),
	regexp.MustCompile(`(?i)\b(rd|rmdir)\b.*/s`),
	// 磁盘格式化 / 底层擦写
	regexp.MustCompile(`(?i)\b(mkfs|format)\b`),
	regexp.MustCompile(`\bdd\b.*\bof=/dev/`),
	regexp.MustCompile(`>\s*/dev/(sd|hd|nvme|disk)`),
	// 关机 / 重启 / 停机
	regexp.MustCompile(`(?i)\b(shutdown|reboot|halt|poweroff|init\s+0|init\s+6)\b`),
	// fork 炸弹
	regexp.MustCompile(`:\(\)\s*\{.*\|.*&\s*\}`),
	// 远程内容直接管道给 shell 执行
	regexp.MustCompile(`(?i)\b(curl|wget)\b[^|]*\|\s*(sudo\s+)?(sh|bash|zsh)\b`),
	// 覆盖系统关键目录
	regexp.MustCompile(`>\s*/(etc|boot|sys|proc)/`),
	// 对根目录递归改权限 / 属主
	regexp.MustCompile(`(?i)\bchmod\b\s+-R\s+.*\s+/\s*$`),
	regexp.MustCompile(`(?i)\bchown\b\s+-R\s+.*\s+/\s*$`),
	// 危险提权后的破坏性操作前缀（sudo rm 等已被上面覆盖，这里兜底磁盘写入）
	regexp.MustCompile(`(?i)\bsudo\b.*\b(mkfs|dd|shutdown|reboot)\b`),
	// 借解释器内联执行删除类操作，绕过 rm 拦截（python/node/perl/ruby ...）
	regexp.MustCompile(`(?i)\b(python[0-9.]*|node|deno|bun|perl|ruby|php)\b.*\b(rmtree|rmdir|removedirs|os\.remove|os\.unlink|unlink|rmsync|rm\s*-rf)`),
	// 通过 -c/-e/-p 传入内联脚本且包含删除/擦除关键字
	regexp.MustCompile(`(?i)-[cep]\b.*\b(rmtree|unlink|rmsync|remove\(|shutil)`),
	// cd .. 跳出工作区 + 管道写入操作
	regexp.MustCompile(`\bcd\b\s+\.\.(/|\\)`),
	// echo/write 覆盖工作区外的文件
	regexp.MustCompile(`>\s*\.\./`),
}

// checkDanger 判断命令是否危险。返回命中的原因（空字符串表示安全）。
func CheckDanger(command string) string {
	c := strings.TrimSpace(command)
	for _, re := range dangerousPatterns {
		if re.MatchString(c) {
			return "命中危险命令拦截规则：" + re.String()
		}
	}
	return ""
}

