func TestCheckPath(t *testing.T) {
	// 设置工作区为临时目录
	tmpDir := t.TempDir()
	SetWorkspace(tmpDir)

	// 在工作区内创建子目录和文件
	validSub := filepath.Join(tmpDir, "subdir")
	os.Mkdir(validSub, 0755)
	validFile := filepath.Join(tmpDir, "test.go")
	os.WriteFile(validFile, []byte("package main"), 0644)

	tests := []struct {
		name    string
		path    string
		wantErr bool
	}{
		// 工作区内路径
		{name: "workspace root", path: tmpDir, wantErr: false},
		{name: "subdir", path: "subdir", wantErr: false},
		{name: "file", path: "test.go", wantErr: false},

		// 相对路径但不越界
		{name: "nested relative", path: "subdir/../test.go", wantErr: false},
		{name: "dot", path: ".", wantErr: false},

		// 越界路径
		{name: "parent dir", path: "..", wantErr: true},
		{name: "parent file", path: "../outside.txt", wantErr: true},
		{name: "deep escape", path: "../../etc/passwd", wantErr: true},
		{name: "absolute escape", path: "/etc/passwd", wantErr: true},
		{name: "Windows absolute escape", path: "C:\\Windows\\System32", wantErr: true},
		{name: "sandwich escape", path: "subdir/../../etc", wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := CheckPath(tt.path)
			if (err != nil) != tt.wantErr {
				t.Errorf("CheckPath(%q) error=%v, wantErr=%v", tt.path, err, tt.wantErr)
			}
		})
	}
}

func TestCheckPathUninitialized(t *testing.T) {
	// 未设置工作区时不应拦截
	oldWs := workspace
	workspace = ""
	defer func() { workspace = oldWs }()

	if err := CheckPath("../anything"); err != nil {
		t.Errorf("未初始化时不应拦截，但返回了错误: %v", err)
	}
}

func TestCheckShell(t *testing.T) {
	tmpDir := t.TempDir()
	SetWorkspace(tmpDir)

	tests := []struct {
		name    string
		cmd     string
		wantErr bool
	}{
		// 安全命令
		{name: "no cd", cmd: "go build ./...", wantErr: false},
		{name: "cd to valid sub", cmd: "cd subdir && ls", wantErr: false},

		// cd 越界
		{name: "cd parent", cmd: "cd ..", wantErr: true},
		{name: "cd absolute outside", cmd: "cd /etc", wantErr: true},
		{name: "cd Windows outside", cmd: "cd C:\\Windows", wantErr: true},
		{name: "cd with quotes", cmd: "cd \"..\"", wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := CheckShell(tt.cmd)
			if (err != nil) != tt.wantErr {
				t.Errorf("CheckShell(%q) error=%v, wantErr=%v", tt.cmd, err, tt.wantErr)
			}
		})
	}
